'use strict';
const source='../pentagon-carousel-2026-11-02/';
const profiles=[['Steven Fordant','Basketball · Marseille','coach-basketball-640.webp'],['Madison Seck','Football · Paris','coach-football-640.webp'],['Studio Form Marseille','Fitness · Marseille','coach-fitness-640.webp']];
const count=document.querySelector('#count');
const sections=[...document.querySelectorAll('section[data-mode]')];
const states=new Map(sections.map(s=>[s,{step:0,n:8}]));
function render(section){const state=states.get(section),ring=section.querySelector('.ring');ring.replaceChildren();for(let i=0;i<state.n;i++){const card=document.createElement('article');card.className='card';if(i<profiles.length){const [name,detail,image]=profiles[i];card.innerHTML=`<img src="${source+image}" alt="Illustration IA de démonstration"><div class="shade"></div><span class="tag">Profil de démonstration</span><div class="copy"><h3>${name}</h3><p>${detail}</p><p>Découvrir le profil ↗</p></div>`;}else{card.classList.add('placeholder');card.innerHTML=`<span class="number">${String(i+1).padStart(2,'0')}</span><span class="tag">Emplacement de maquette</span><div class="copy"><h3>Un prochain profil</h3><p>Pour comparer la composition</p><p>Aucun coach ajouté au catalogue</p></div>`;}ring.append(card);}layout(section);}
function layout(section){const {step,n}=states.get(section),mode=section.dataset.mode,viewport=section.querySelector('.viewport'),ring=section.querySelector('.ring'),size=parseFloat(getComputedStyle(section.querySelector('.card')).width),width=viewport.clientWidth,active=((step%n)+n)%n;const radius=(size+18)/(2*Math.tan(Math.PI/n));ring.style.transform=mode==='polygon'?`translateZ(${-radius}px) rotateY(${-step*360/n}deg)`:'none';[...ring.children].forEach((card,i)=>{let d=((i-active+n)%n);if(d>n/2)d-=n;card.dataset.active=String(i===active);card.setAttribute('aria-hidden',String(i!==active));card.inert=i!==active;let opacity=1;if(mode==='polygon'){card.style.transform=`rotateY(${i*360/n}deg) translateZ(${radius}px)`;}else if(mode==='ellipse'){const theta=d*2*Math.PI/n,rx=Math.max(size*.9,Math.min(width*.43,900));const x=Math.sin(theta)*rx,z=(Math.cos(theta)-1)*180;card.style.transform=`translate3d(${x}px,0,${z}px) rotateY(${-Math.sin(theta)*32}deg)`;opacity=Math.abs(theta)>Math.PI*.66?.16:1;card.style.zIndex=String(Math.round(Math.cos(theta)*100)+100);}else{const gap=Math.min(size*.88,Math.max(120,(width-size)/4.2));card.style.transform=`translate3d(${d*gap}px,${Math.min(Math.abs(d),3)*9}px,${-Math.abs(d)*65}px) rotateY(${-Math.sign(d)*Math.min(32,Math.abs(d)*14)}deg)`;opacity=Math.abs(d)>3?0:1;card.style.zIndex=String(n-Math.abs(d));}card.style.opacity=opacity;});section.querySelector('[role="status"]').textContent=`Carte ${active+1} / ${n} · ${n} ${mode==='polygon'?'faces':'cartes'}`;section.dataset.active=String(active);section.dataset.count=String(n);}
function move(section,delta){states.get(section).step+=delta;layout(section);}
sections.forEach(section=>{let pointer=null;section.querySelectorAll('button[data-dir]').forEach(button=>button.addEventListener('click',()=>move(section,Number(button.dataset.dir))));const viewport=section.querySelector('.viewport');viewport.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(section,e.key==='ArrowRight'?1:-1);}});viewport.addEventListener('pointerdown',e=>{if(e.isPrimary)pointer={x:e.clientX,y:e.clientY};});viewport.addEventListener('pointerup',e=>{if(pointer){const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy)*1.2)move(section,dx<0?1:-1);}pointer=null;});viewport.addEventListener('pointercancel',()=>pointer=null);render(section);});
count.addEventListener('change',()=>sections.forEach(section=>{states.set(section,{step:0,n:Number(count.value)});render(section);}));window.addEventListener('resize',()=>sections.forEach(layout));
